//! End-to-end shape test on a committed, deterministic tiny synthetic cell
//! (`tests/fixtures/tiny1/`, generated by
//! `tests/fixtures/generate_tiny1.py` from the real TGMS Python harness --
//! see that script for how the bundle's `oracle.jsonl` digests were
//! produced): the unit-level shape test --
//! "unit tests for ... each family's dataflow on a tiny synthetic cell
//! (deterministic, in external/ivm-dd/tests/), run on xzgpu with
//! `cargo test`".
//!
//! Every registered artifact's epoch-0 digest from `dataflow::run` must
//! equal the oracle's own `result_digest` for that artifact at epoch 0
//! (the same comparison the shape test on a real exported cell performs
//! against a real exported cell -- this is that comparison's offline,
//! always-available twin).

use ivm_dd::{changelog, dataflow, export::CellBundle};
use std::path::Path;

#[test]
fn tiny1_epoch0_digests_match_the_real_tgms_oracle() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/tiny1");
    if !dir.join("export-manifest.json").exists() {
        eprintln!(
            "SKIP: tests/fixtures/tiny1/ not present yet (run \
             tests/fixtures/generate_tiny1.py to produce it) -- this is a \
             soft skip, not a pass: the shape-test gate is not satisfied \
             without this fixture in place."
        );
        return;
    }
    let bundle = CellBundle::load(&dir).expect("load tiny1 bundle");
    let cl = changelog::build(&bundle);
    let n_artifacts = bundle.artifacts.len();
    let outcome = dataflow::run(cl, bundle.artifacts.clone());

    let row0 = bundle.oracle.first().expect("tiny1 oracle.jsonl must have an epoch-0 row");
    let op_of: std::collections::HashMap<&str, &str> =
        bundle.artifacts.iter().map(|a| (a.name.as_str(), a.op.as_str())).collect();

    let mut agree = 0usize;
    let mut failures: Vec<String> = Vec::new();
    for (name, oracle_digest) in &row0.digests {
        let Some(od) = oracle_digest else { continue };
        match outcome.epoch0_digests.get(name) {
            Some(ours) if ours == od => agree += 1,
            Some(ours) => failures.push(format!(
                "{name} (op={}): oracle={od} ours={ours}",
                op_of.get(name.as_str()).unwrap_or(&"?")
            )),
            None => failures.push(format!(
                "{name} (op={}): oracle={od}, ivm-dd produced nothing",
                op_of.get(name.as_str()).unwrap_or(&"?")
            )),
        }
    }
    assert!(n_artifacts >= 13, "tiny1 fixture should register at least one artifact per family");
    assert!(
        failures.is_empty(),
        "{} of {} artifacts disagreed with the TGMS oracle at epoch 0:\n{}",
        failures.len(),
        row0.digests.len(),
        failures.join("\n")
    );
    assert!(agree > 0, "no artifact had a comparable oracle digest -- fixture is empty/misread");
}

#[test]
fn tiny1_post_burst_digests_match_the_real_tgms_oracle() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/tiny1");
    if !dir.join("export-manifest.json").exists() {
        eprintln!("SKIP: tests/fixtures/tiny1/ not present yet.");
        return;
    }
    let bundle = CellBundle::load(&dir).expect("load tiny1 bundle");
    let cl = changelog::build(&bundle);
    let outcome = dataflow::run(cl, bundle.artifacts.clone());

    // Reconstruct "current known digest per artifact" the same way
    // record.rs's oracle_agreement does, and check every oracle row, not
    // just epoch 0 -- this is what actually exercises the bursts/retract
    // +insert path, not just the initial load.
    let mut running = outcome.epoch0_digests.clone();
    let mut failures: Vec<String> = Vec::new();
    let mut checked = 0usize;
    for (burst, oracle_row) in outcome.bursts.iter().zip(bundle.oracle.iter().skip(1)) {
        for (name, digest) in &burst.digests {
            running.insert(name.clone(), digest.clone());
        }
        for (name, oracle_digest) in &oracle_row.digests {
            let Some(od) = oracle_digest else { continue };
            checked += 1;
            match running.get(name) {
                Some(ours) if ours == od => {}
                Some(ours) => failures.push(format!(
                    "epoch {}: {name}: oracle={od} ours={ours}",
                    oracle_row.epoch
                )),
                None => failures.push(format!(
                    "epoch {}: {name}: oracle={od}, ivm-dd never produced a value",
                    oracle_row.epoch
                )),
            }
        }
    }
    assert!(checked > 0, "tiny1 fixture should have at least one post-epoch-0 burst to check");
    assert!(failures.is_empty(), "post-burst oracle disagreements:\n{}", failures.join("\n"));
}
